	@Override
	public SuccessRes insertDocument(List<ProductDocumentMasterSaveReq> reqList) {
		SimpleDateFormat sdformat = new SimpleDateFormat("dd/MM/YYYY");
		SuccessRes res = new SuccessRes();
	  ProductDocumentMaster	saveData = new ProductDocumentMaster();
		List<ProductDocumentMaster> list = new ArrayList<ProductDocumentMaster>();
		DozerBeanMapper dozerMapper = new DozerBeanMapper();

		try {
			for (ProductDocumentMasterSaveReq req : reqList) {
				Calendar cal = new GregorianCalendar();
				cal.setTime(req.getEffectiveDateStart());  cal.set(Calendar.HOUR_OF_DAY, 23); cal.set(Calendar.MINUTE, 59);
				Date startDate = cal.getTime() ;
				Date today = new Date();
				cal.setTime(req.getEffectiveDateStart());  cal.add(Calendar.DAY_OF_MONTH, -1); cal.set(Calendar.HOUR_OF_DAY, today.getHours()); cal.set(Calendar.MINUTE, today.getMinutes());
				cal.set(Calendar.SECOND, today.getSeconds());
				Date oldEndDate = cal.getTime() ;
				cal.setTime(req.getEffectiveDateStart());  cal.set(Calendar.HOUR_OF_DAY, today.getHours()); cal.set(Calendar.MINUTE, today.getMinutes()) ;
				cal.set(Calendar.SECOND, today.getSeconds());
				Date effDate = cal.getTime();
				Date endDate = sdformat.parse("12/12/2050");

				String documentId = "";

				// Update
				// Get Less than Equal Today Record
				// Criteria
				documentId = req.getDocumentId().toString();
				CriteriaBuilder cb = em.getCriteriaBuilder();
				CriteriaQuery<ProductDocumentMaster> query = cb.createQuery(ProductDocumentMaster.class);

				// Find All
				Root<ProductDocumentMaster> b = query.from(ProductDocumentMaster.class);

				// Select
				query.select(b);

				// Effective Date Max Filter
				Subquery<Long> effectiveDate = query.subquery(Long.class);
				Root<ProductDocumentMaster> ocpm1 = effectiveDate.from(ProductDocumentMaster.class);
				effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
				Predicate a1 = cb.equal(ocpm1.get("documentId"), b.get("documentId"));
				Predicate a2 = cb.equal(ocpm1.get("sectionId"), b.get("sectionId"));
				Predicate a3 = cb.equal(ocpm1.get("productId"), b.get("productId"));
				Predicate a4 = cb.equal(ocpm1.get("companyId"), b.get("companyId"));
				Predicate a5 = cb.lessThanOrEqualTo(ocpm1.get("effectiveDateStart"), startDate);
				effectiveDate.where(a1, a2,a3,a4,a5);

				// Order By
				// List<Order> orderList = new ArrayList<Order>();
				// orderList.add(cb.asc(b.get("branchName")));

				// Where
				Predicate n1 = cb.equal(b.get("status"),req.getStatus());
				Predicate n2 = cb.equal(b.get("effectiveDateStart"), effectiveDate);
				Predicate n3 = cb.equal(b.get("documentId"), req.getDocumentId());
				Predicate n4 = cb.equal(b.get("sectionId"), req.getSectionId());
				Predicate n5 = cb.equal(b.get("productId"), req.getProductId());
				Predicate n6 = cb.equal(b.get("companyId"), req.getCompanyId());

				query.where(n1, n2, n3,n4,n5,n6);

				// Get Result
				TypedQuery<ProductDocumentMaster> result = em.createQuery(query);
				list = result.getResultList();

				if (list.size() > 0) {
					repo.delete(list.get(0));
				}
				res.setResponse("Document Added Successfully ");
				res.setSuccessId(documentId);

				dozerMapper.map(req, saveData);
				saveData.setDocumentId(Integer.valueOf(documentId));
				saveData.setDocumentDesc(req.getDocumentDesc());
				saveData.setEffectiveDateStart(effDate);
				saveData.setEffectiveDateEnd(endDate);
				saveData.setStatus("Y");
				saveData.setEntryDate(new Date());
				repo.saveAndFlush(saveData);

				if (list.size() > 0) {
					// Update Old Record
					ProductDocumentMaster lastRecord = list.get(0);
					lastRecord.setEffectiveDateEnd(oldEndDate);
					repo.saveAndFlush(lastRecord);
				}

				log.info("Saved Details is ---> " + json.toJson(saveData));
			}
		} catch (Exception e) {
			e.printStackTrace();
			log.info("Exception is --->" + e.getMessage());
			return null;
		}
		return res;
	}


	
